<?php
namespace App\Controllers;
use App\Core\{Controller,Database,Request,Response,Auth};
use App\Services\BackupService;
final class PlatformController extends Controller {
    private const FEATURES=['customers','service_requests','jobs','inventory','inventory_basic','quotations','invoices','payments','scheduling','contracts','reports_basic','reports_advanced','api','customer_portal','analytics','automation','white_label'];
    public function index(): void {
        $db=Database::connection();$tenants=$db->query("SELECT t.*,sp.id plan_id,sp.name plan_name,sp.price_monthly,s.id subscription_id,s.status subscription_status,s.trial_ends_at,s.ends_at,s.amount subscription_amount,(SELECT COUNT(*) FROM users u WHERE u.tenant_id=t.id AND u.deleted_at IS NULL) user_count,(SELECT COUNT(*) FROM branches b WHERE b.tenant_id=t.id AND b.deleted_at IS NULL) branch_count,(SELECT COUNT(*) FROM jobs j WHERE j.tenant_id=t.id AND j.deleted_at IS NULL) job_count,(SELECT COALESCE(SUM(amount),0) FROM subscription_payments p WHERE p.tenant_id=t.id) subscription_paid FROM tenants t LEFT JOIN subscriptions s ON s.id=(SELECT ss.id FROM subscriptions ss WHERE ss.tenant_id=t.id ORDER BY ss.id DESC LIMIT 1) LEFT JOIN subscription_plans sp ON sp.id=s.plan_id WHERE t.status<>'deleted' ORDER BY t.id DESC")->fetchAll();$plans=$db->query("SELECT * FROM subscription_plans WHERE is_active=1 ORDER BY price_monthly")->fetchAll();$mrr=0;$storage=0;$outstanding=0;foreach($tenants as &$t){if(in_array($t['subscription_status'],['trial','active'],true))$mrr+=(float)$t['price_monthly'];$t['storage_usage_mb']=$this->folderMb(BASE_PATH.'/storage/uploads/'.$t['id']);$storage+=$t['storage_usage_mb'];if($t['subscription_status']==='past_due')$outstanding+=(float)($t['subscription_amount']??$t['price_monthly']??0);$o=$db->prepare("SELECT feature_key,enabled,limit_value FROM tenant_feature_overrides WHERE tenant_id=? ORDER BY feature_key");$o->execute([$t['id']]);$t['overrides']=$o->fetchAll();}unset($t);$payments=$db->query("SELECT p.*,t.name tenant_name FROM subscription_payments p JOIN tenants t ON t.id=p.tenant_id ORDER BY p.id DESC LIMIT 30")->fetchAll();$stats=['total'=>count($tenants),'active'=>count(array_filter($tenants,fn($x)=>$x['status']==='active')),'trial'=>count(array_filter($tenants,fn($x)=>$x['subscription_status']==='trial')),'suspended'=>count(array_filter($tenants,fn($x)=>$x['status']==='suspended')),'mrr'=>$mrr,'arr'=>$mrr*12,'users'=>array_sum(array_column($tenants,'user_count')),'jobs'=>array_sum(array_column($tenants,'job_count')),'storage'=>$storage,'outstanding'=>$outstanding];$this->view('superadmin/index',['title'=>'Platform Super Admin','tenants'=>$tenants,'stats'=>$stats,'plans'=>$plans,'features'=>self::FEATURES,'subscriptionPayments'=>$payments]);
    }
    public function create(): void {
        $this->requireCsrf();$name=trim((string)Request::input('name'));$code=strtoupper(trim((string)Request::input('company_code')));$adminEmail=strtolower(trim((string)Request::input('admin_email')));$planId=(int)Request::input('plan_id');$password=(string)Request::input('admin_password');if($name===''||$code===''||!filter_var($adminEmail,FILTER_VALIDATE_EMAIL)||!$planId||strlen($password)<8)Response::json(['success'=>false,'message'=>'Company, code, valid admin email, plan, dan password minimal 8 karakter wajib.','errors'=>[]],422);$db=Database::connection();$db->beginTransaction();try{$db->prepare("INSERT INTO tenants(name,company_code,business_type,address,phone,email,website,tax_number,currency,default_tax,timezone,language,invoice_prefix,job_prefix,quotation_prefix,status,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,'active',NOW(),NOW())")->execute([$name,$code,Request::input('business_type'),Request::input('address'),Request::input('phone'),Request::input('email'),Request::input('website'),Request::input('tax_number'),Request::input('currency','IDR'),(float)Request::input('default_tax',0),Request::input('timezone','Asia/Makassar'),Request::input('language','id'),Request::input('invoice_prefix','INV'),Request::input('job_prefix','JOB'),Request::input('quotation_prefix','QUO')]);$tenant=(int)$db->lastInsertId();$trialDays=max(0,(int)Request::input('trial_days',14));$db->prepare("INSERT INTO subscriptions(tenant_id,plan_id,status,starts_at,trial_ends_at,amount,created_at,updated_at) SELECT ?,?,'trial',NOW(),DATE_ADD(NOW(),INTERVAL ? DAY),price_monthly,NOW(),NOW() FROM subscription_plans WHERE id=?")->execute([$tenant,$planId,$trialDays,$planId]);$db->prepare("INSERT INTO branches(tenant_id,name,address,status,created_at,updated_at) VALUES(?,'Main Branch',?,'active',NOW(),NOW())")->execute([$tenant,Request::input('address')]);$branch=(int)$db->lastInsertId();$db->prepare("INSERT INTO users(tenant_id,branch_id,name,email,password_hash,is_platform_admin,status,created_at,updated_at) VALUES(?,?,?,?,?,0,'active',NOW(),NOW())")->execute([$tenant,$branch,Request::input('admin_name','Company Owner'),$adminEmail,password_hash($password,PASSWORD_DEFAULT)]);$uid=(int)$db->lastInsertId();$db->prepare("INSERT INTO roles(tenant_id,name,code,is_system,created_at,updated_at) VALUES(?,'Company Owner','owner',1,NOW(),NOW())")->execute([$tenant]);$role=(int)$db->lastInsertId();$db->prepare("INSERT INTO role_permissions(role_id,permission_id) SELECT ?,id FROM permissions")->execute([$role]);$db->prepare("INSERT INTO user_roles(tenant_id,user_id,role_id) VALUES(?,?,?)")->execute([$tenant,$uid,$role]);$db->commit();}catch(\Throwable $e){if($db->inTransaction())$db->rollBack();Response::json(['success'=>false,'message'=>'Unable to create tenant: '.$e->getMessage(),'errors'=>[]],422);}Response::json(['success'=>true,'message'=>'Tenant '.$name.' berhasil dibuat. Admin: '.$adminEmail,'data'=>['reload'=>true]]);
    }
    public function status(string $id): void {$this->requireCsrf();$status=(string)Request::input('status');if(!in_array($status,['active','suspended'],true))Response::json(['success'=>false,'message'=>'Status invalid.','errors'=>[]],422);Database::connection()->prepare("UPDATE tenants SET status=?,updated_at=NOW() WHERE id=? AND status<>'deleted'")->execute([$status,(int)$id]);Response::json(['success'=>true,'message'=>'Tenant status updated.','data'=>['reload'=>true]]);}
    public function delete(string $id): void {$this->requireCsrf();$db=Database::connection();$db->beginTransaction();try{$db->prepare("UPDATE tenants SET status='deleted',updated_at=NOW() WHERE id=?")->execute([(int)$id]);$db->prepare("UPDATE users SET status='inactive',updated_at=NOW() WHERE tenant_id=?")->execute([(int)$id]);$db->prepare("UPDATE subscriptions SET status='cancelled',updated_at=NOW() WHERE tenant_id=? AND status NOT IN('cancelled','expired')")->execute([(int)$id]);$db->commit();}catch(\Throwable $e){if($db->inTransaction())$db->rollBack();throw $e;}Response::json(['success'=>true,'message'=>'Tenant archived/deleted safely. Transaction data retained for audit.','data'=>['reload'=>true]]);}
    public function subscription(string $id): void {$this->requireCsrf();$plan=(int)Request::input('plan_id');$status=(string)Request::input('status','active');if(!in_array($status,['trial','active','past_due','expired','cancelled'],true))$status='active';$days=(int)Request::input('extend_days',0);$db=Database::connection();$s=$db->prepare("SELECT id FROM subscriptions WHERE tenant_id=? ORDER BY id DESC LIMIT 1");$s->execute([(int)$id]);$sid=$s->fetchColumn();if($sid){$db->prepare("UPDATE subscriptions SET plan_id=COALESCE(NULLIF(?,0),plan_id),status=?,ends_at=CASE WHEN ?>0 THEN DATE_ADD(COALESCE(ends_at,NOW()),INTERVAL ? DAY) ELSE ends_at END,trial_ends_at=CASE WHEN status='trial' AND ?>0 THEN DATE_ADD(COALESCE(trial_ends_at,NOW()),INTERVAL ? DAY) ELSE trial_ends_at END,updated_at=NOW() WHERE id=?")->execute([$plan,$status,$days,$days,$days,$days,$sid]);}Response::json(['success'=>true,'message'=>'Subscription updated.','data'=>['reload'=>true]]);}
    public function resetAdmin(string $id): void {$this->requireCsrf();$password=(string)Request::input('password');if(strlen($password)<8)Response::json(['success'=>false,'message'=>'Password minimal 8 karakter.','errors'=>[]],422);$db=Database::connection();$q=$db->prepare("SELECT u.id,u.email FROM users u JOIN user_roles ur ON ur.user_id=u.id AND ur.tenant_id=u.tenant_id JOIN roles r ON r.id=ur.role_id AND r.tenant_id=u.tenant_id WHERE u.tenant_id=? AND r.code='owner' AND u.deleted_at IS NULL ORDER BY u.id LIMIT 1");$q->execute([(int)$id]);$u=$q->fetch();if(!$u)Response::json(['success'=>false,'message'=>'Tenant owner/admin tidak ditemukan.','errors'=>[]],404);$db->prepare("UPDATE users SET password_hash=?,status='active',updated_at=NOW() WHERE id=? AND tenant_id=?")->execute([password_hash($password,PASSWORD_DEFAULT),$u['id'],(int)$id]);$db->prepare("UPDATE user_sessions SET revoked_at=NOW() WHERE user_id=? AND tenant_id=? AND revoked_at IS NULL")->execute([$u['id'],(int)$id]);Response::json(['success'=>true,'message'=>'Owner password reset for '.$u['email'].'.','data'=>['reload'=>true]]);}
    public function feature(string $id): void {$this->requireCsrf();$key=trim((string)Request::input('feature_key'));if(!in_array($key,self::FEATURES,true))Response::json(['success'=>false,'message'=>'Feature invalid.','errors'=>[]],422);$enabled=(int)(bool)Request::input('enabled');Database::connection()->prepare("INSERT INTO tenant_feature_overrides(tenant_id,feature_key,enabled,limit_value,updated_at) VALUES(?,?,?,?,NOW()) ON DUPLICATE KEY UPDATE enabled=VALUES(enabled),limit_value=VALUES(limit_value),updated_at=NOW()")->execute([(int)$id,$key,$enabled,Request::input('limit_value')?:null]);Response::json(['success'=>true,'message'=>'Tenant feature override updated.','data'=>['reload'=>true]]);}
    public function payment(string $id): void {$this->requireCsrf();$amount=(float)Request::input('amount');if($amount<=0)Response::json(['success'=>false,'message'=>'Amount harus lebih dari 0.','errors'=>[]],422);$db=Database::connection();$q=$db->prepare("SELECT id FROM subscriptions WHERE tenant_id=? ORDER BY id DESC LIMIT 1");$q->execute([(int)$id]);$sid=$q->fetchColumn();if(!$sid)Response::json(['success'=>false,'message'=>'Subscription tidak ditemukan.','errors'=>[]],404);$db->prepare("INSERT INTO subscription_payments(tenant_id,subscription_id,payment_date,amount,method,reference,notes,created_at) VALUES(?,?,COALESCE(?,CURDATE()),?,?,?,?,NOW())")->execute([(int)$id,$sid,Request::input('payment_date')?:null,$amount,Request::input('method'),Request::input('reference'),Request::input('notes')]);$db->prepare("UPDATE subscriptions SET status='active',updated_at=NOW() WHERE id=? AND status='past_due'")->execute([$sid]);Response::json(['success'=>true,'message'=>'Subscription payment recorded.','data'=>['reload'=>true]]);}
    public function globalBackup(): void {$this->requireCsrf();$db=Database::connection();$ids=$db->query("SELECT id FROM tenants WHERE status<>'deleted' ORDER BY id")->fetchAll(\PDO::FETCH_COLUMN);$files=[];$errors=[];foreach($ids as $id){try{$files[]=BackupService::tenantJson((int)$id,Auth::id());}catch(\Throwable $e){$errors[]='Tenant '.$id.': '.$e->getMessage();}}$dir=BASE_PATH.'/storage/backups/platform';if(!is_dir($dir))mkdir($dir,0750,true);$manifest=$dir.'/global-'.date('Ymd-His').'.json';file_put_contents($manifest,json_encode(['generated_at'=>date(DATE_ATOM),'files'=>$files,'errors'=>$errors],JSON_PRETTY_PRINT|JSON_UNESCAPED_SLASHES));Response::json(['success'=>true,'message'=>'Global backup completed: '.count($files).' tenant(s)'.($errors?' with '.count($errors).' error(s).':'.'),'data'=>['reload'=>true]]);}
    private function folderMb(string $path): float {if(!is_dir($path))return 0;$bytes=0;$it=new \RecursiveIteratorIterator(new \RecursiveDirectoryIterator($path,\FilesystemIterator::SKIP_DOTS));foreach($it as $f)if($f->isFile())$bytes+=$f->getSize();return round($bytes/1048576,2);}
}
